cat > $TMPDIR/i013/analyze3.py << 'PYEOF'
#!/usr/bin/env python3
"""For each skb_header_pointer assignment, find the enclosing function and check
whether the assigned pointer is dereferenced before any NULL validation, AND
whether the call is on a receive path (_rcv/_recv/ptype handler)."""
import os, re, subprocess
ROOT = "/mnt/raid/home/yangshuangning/vuln_variant_search/experiments/clairvoyant_variant_search/runs/C6/public/snapshots/s02"
files = subprocess.run(["find", os.path.join(ROOT,"net"), os.path.join(ROOT,"drivers","net"),
                        "-name","*.c"], capture_output=True, text=True).stdout.split()
pat = re.compile(r'^\s*(?:const\s+)?[\w\s\*]*?\b(\w+)\s*=\s*(?:__)?skb_header_pointer(?:_with_crop)?\s*\(')

def func_span(lines, idx):
    s = idx
    while s > 0:
        if re.match(r'^[A-Za-z_]', lines[s]) and (re.search(r'\)\s*$', lines[s]) or re.search(r'\)\s*\{', lines[s])):
            break
        s -= 1
    j = s
    while j < len(lines) and '{' not in lines[j]:
        j += 1
    if j >= len(lines): return None
    depth = 0
    k = j
    while k < len(lines):
        depth += lines[k].count('{') - lines[k].count('}')
        if depth == 0 and k > j:
            return (s, k)
        if depth <= 0 and '{' in lines[j]:
            return (s, k)
        k += 1
    return (s, len(lines)-1)

out = []
for f in files:
    try: src = open(f, errors='replace').read()
    except: continue
    lines = src.split('\n')
    for idx, line in enumerate(lines):
        m = pat.match(line)
        if not m: continue
        var = m.group(1)
        sp = func_span(lines, idx)
        if not sp: continue
        fs, fe = sp
        body = lines[fs:fe+1]
        status = None
        for k in range(idx+1, fe+1):
            l = lines[k]
            # NULL checks
            if re.search(r'\b'+re.escape(var)+r'\s*==\s*NULL', l) or re.search(r'\b!\s*'+re.escape(var)+r'\b', l):
                status = 'checked'; break
            if re.search(r'\b'+re.escape(var)+r'\s*->', l) or re.search(r'\b'+re.escape(var)+r'\s*\[', l) or re.search(r'\*\s*'+re.escape(var)+r'\b', l):
                status = 'deref@%d'%(k+1); break
        if status and status.startswith('deref'):
            funcname = re.match(r'^\s*(?:static\s+)?[\w\s\*]+?(\w+)\s*\(', lines[fs]) 
            fname = funcname.group(1) if funcname else '?'
            out.append((f.replace(ROOT+'/',''), idx+1, fname, var, lines[idx].strip(), lines[int(status.split('@')[1])-1].strip(), status.split('@')[1]))

print("candidates:", len(out))
for o in out:
    print(f"{o[0]}:{o[1]} [{o[2]}] var={o[3]}")
    print(f"   ASSIGN: {o[4]}")
    print(f"   DEREF ({o[6]}): {o[5]}")
    print()
PYEOF
