import re, os, sys

root = "snapshots/s02"
pat_call = re.compile(r'\bskb_header_pointer\s*\(|__skb_header_pointer\s*\(|skb_header_pointer_with_crop\s*\(')
pat_var = re.compile(r'(\w+)\s*=\s*(?:__)?skb_header_pointer(?:_with_crop)?\s*\(')

# find call sites, then examine the following ~10 lines for a NULL check of the assignee
hits = []
for dirpath, dirs, files in os.walk(root):
    dirs[:] = [d for d in dirs if d not in ('Documentation','tools','samples')]
    for f in files:
        if not f.endswith('.c'):
            continue
        p = os.path.join(dirpath, f)
        try:
            lines = open(p, errors='replace').read().split('\n')
        except Exception:
            continue
        for i, l in enumerate(lines):
            if pat_call.search(l):
                # gather assignee
                m = pat_var.search(l)
                assignee = m.group(1) if m else None
                # look ahead up to 12 lines for a NULL check
                window = lines[i:i+13]
                checked = False
                if assignee:
                    for w in window[1:]:
                        if re.search(r'\b'+re.escape(assignee)+r'\s*(!|==|!=)|if\s*\(\s*!?\s*'+re.escape(assignee), w):
                            checked = True
                            break
                # is assignee dereferenced later?
                if assignee and not checked:
                    later = '\n'.join(lines[i+1:i+25])
                    if re.search(re.escape(assignee)+r'\s*->', later) or re.search(re.escape(assignee)+r'\s*\[', later):
                        hits.append((p, i+1, l.strip(), assignee))
for h in hits:
    print("%s:%d assignee=%s :: %s" % (h[0], h[1], h[3], h[2]))
print("TOTAL", len(hits))
