cat > $TMPDIR/scan_cast.py << 'PYEOF'
import re, os

root = "snapshots/s02"
pat_cast = re.compile(r'\(\s*struct\s+\w+\s*\*s?\s*\)\s*skb->data')
# collect sites where a cast of skb->data occurs in a function that never calls pskb_may_pull/skb_linearize before the cast line
results = []
for dirpath, dirs, files in os.walk(root):
    dirs[:] = [d for d in dirs if d not in ('Documentation','tools','samples')]
    if '/net/' not in dirpath and '/drivers/net/' not in dirpath:
        continue
    for f in files:
        if not f.endswith('.c'):
            continue
        p = os.path.join(dirpath, f)
        try:
            lines = open(p, errors='replace').read().split('\n')
        except Exception:
            continue
        # crude function boundaries: lines starting with '{' or '}' at col 0
        for i, l in enumerate(lines):
            m = pat_cast.search(l)
            if not m:
                continue
            # find enclosing function start
            fstart = 0
            for j in range(i, -1, -1):
                if lines[j].startswith('}') or lines[j].startswith('{'):
                    fstart = j
                    break
            body = lines[fstart:i+1]
            guard = any(('pskb_may_pull' in b or 'skb_linearize' in b or 'skb_headlen' in b or 'skb_is_nonlinear' in b or 'skb_pagelen' in b) for b in body)
            if not guard:
                results.append((p, i+1, l.strip()))
for r in results:
    print("%s:%d :: %s" % r)
print("TOTAL", len(results))
PYEOF
python3 $TMPDIR/scan_cast.py > $TMPDIR/cast_noguard.txt 2>&1; tail -1 $TMPDIR/cast_noguard.txt; head -70 $TMPDIR/cast_noguard.txt

